import os
from openpyxl import load_workbook
out = os.environ['OUT_XLSX']
wb = load_workbook(out)
ws = wb['Sheet1']
for r in range(4, 16):
    c = ws.cell(row=r, column=3).value
    if c is None:
        v = 0
    elif 5 <= c <= 6:
        v = 5
    elif 3 <= c <= 4:
        v = 3.75
    elif 1 <= c <= 2:
        v = 1
    else:
        v = 0
    ws.cell(row=r, column=4).value = v
wb.save(out)
print('done')
